import torch

def run(x, p, train):
    return torch.feature_dropout(x, p, train)

def valid(ref_outputs, sol_outputs, inputs, ctx):
    x = inputs[0]
    p = ctx['p']
    sol = sol_outputs[0]
    batch_size, num_channels = (x.shape[0], x.shape[1])
    scale = 1.0 / (1.0 - p)
    xf = x.float().reshape(batch_size, num_channels, -1)
    sf = sol.float().reshape(batch_size, num_channels, -1)
    dropped = 0
    total = batch_size * num_channels
    for b in range(batch_size):
        for c in range(num_channels):
            channel_out = sf[b, c]
            channel_inp = xf[b, c]
            if torch.all(channel_out.abs() < 1e-06):
                dropped += 1
            else:
                expected = channel_inp * scale
                if not torch.allclose(channel_out, expected, rtol=0.05, atol=0.01):
                    diff = (channel_out - expected).abs().max().item()
                    return {'passed': False, 'message': f'Channel ({b},{c}) max diff={diff:.6f} exceeds tolerance', 'metrics': {}}
    actual_p = dropped / total
    if total < 50:
        tolerance = max(0.3, 2.0 / total ** 0.5)
    else:
        tolerance = 0.2
    if abs(actual_p - p) > tolerance:
        return {'passed': False, 'message': f'Dropout ratio {actual_p:.4f} differs from expected {p} by more than tolerance {tolerance}', 'metrics': {'actual_p': actual_p}}
    return {'passed': True, 'message': f'Statistical check passed: {dropped}/{total} channels dropped (p={p})', 'metrics': {'actual_p': actual_p}}
